const keys = await generateKeyPair({
    kind: 'rsa',
    modulusLength: 2048,
});
// Export RSA key with AES-256-CBC
const pem = await exportEncryptedPkcs1Pem(keys.privateKey, {
    password: 'password',
    cipher: 'AES-256-CBC',
});
// Import with the same password
const privateKey = unwrap(await importEncryptedPkcs1Pem(pem, 'password', {
    kind: 'rsa',
    scheme: 'pkcs1-v1_5',
}));
